function RequireAuth({ children }) {
  const { user, loading } = useSession();
  if (loading) return <Spinner />;
  if (!user) return <Navigate to="/login" replace />;
  return children;
}

function OrderList({ status }) {
  const { data } = useServerQuery(['orders'], () =>
    fetchOrders(status),
  );
  return <OrderTable rows={data} />;
}

async function addTodoOptimistic(cache, todo) {
  await cache.cancelQueries(['todos']);
  const previous = cache.getData(['todos']);
  cache.setData(['todos'], (old) => [...old, todo]);
  return previous; // restored if the mutation fails
}

function LineItems({ items, onRemove }) {
  return items.map((item, i) => (
    <div key={i}>
      <input defaultValue={item.name} />
      <button onClick={() => onRemove(i)}>Remove</button>
    </div>
  ));
}

